-- Validación 1: colaboradores Baja incorporados/presentes.
SELECT COUNT(*) AS bajas_incorporadas
FROM public.agenda_2026
WHERE "No. Empleado" IN ('78', '80', '211', '223', '248', '483', '813', '975', '998', '1040', '1129', '1407', '1481', '1507', '1518', '1520', '1568', '1578', '1605', '1608', '1609', '1650', '1668', '1680', '1716', '1721', '1391-2', '1509-2', '1574-2', '317-2', '782-2', '91-2', '1736', '1735')
  AND "Estatus" = 'Baja';

-- Validación 2: ninguno de estos colaboradores debe aparecer como VACANTE.
SELECT "No. Empleado", "Nombre", "Estatus"
FROM public.agenda_2026
WHERE "No. Empleado" IN ('78', '80', '211', '223', '248', '483', '813', '975', '998', '1040', '1129', '1407', '1481', '1507', '1518', '1520', '1568', '1578', '1605', '1608', '1609', '1650', '1668', '1680', '1716', '1721', '1391-2', '1509-2', '1574-2', '317-2', '782-2', '91-2', '1736', '1735')
  AND upper(coalesce("Nombre", '')) = 'VACANTE';

-- Validación 3: números de empleado duplicados. Debe regresar 0 filas.
SELECT "No. Empleado", COUNT(*) AS total
FROM public.agenda_2026
WHERE "No. Empleado" IS NOT NULL
  AND btrim("No. Empleado"::text) <> ''
GROUP BY "No. Empleado"
HAVING COUNT(*) > 1;

-- Validación 4: resumen por estatus.
SELECT "Estatus", COUNT(*) AS total
FROM public.agenda_2026
GROUP BY "Estatus"
ORDER BY "Estatus";

COMMIT;
